					<a href="tel:<?= str_replace( [
						' ',
						'-',
						'(',
						')'
					], '', $contact['phones'][0]['number'] ); ?>"
					   class="footer-calls__phone"><span><?= $contact['city'] ?>:</span> <?= $contact['phones'][0]['number']; ?>
					</a>
				<?php endforeach; ?>
			</div>
		</div>
	<?php endif; ?>
</footer>
<script>
	document.addEventListener('DOMContentLoaded', function () {
		const buttonUp = document.querySelector('.up-button');
		const footerCalls = document.querySelector('.footer-calls');

		if (buttonUp) {
			function checkViewport() {

				if (window.scrollY > 300 && !footerCalls.classList.contains('footer-calls--active')) {
					buttonUp.classList.add('up-button--active');
				} else {
					buttonUp.classList.remove('up-button--active');
				}
			}

			buttonUp.addEventListener('click', function () {
				document.documentElement.scrollTo({
					top: 0,
					left: 0,
					behavior: "smooth",
				});
			})


			window.addEventListener('scroll', checkViewport);
			checkViewport();
		}
	});
</script>

